import{_ as s,C as r,o as a,c as n,j as e,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-run-control-hover.png",p="/screenshots/vscode-run-control-paused-page.png",c="/diagrams/run-control.svg",P=JSON.parse('{"title":"Pause and step from the editor","description":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor.","frontmatter":{"title":"Pause and step from the editor","description":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:title","content":"Pause and step from the editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Pause and step a Playwright run from VS Code or a JetBrains IDE, follow its stopped line and watch or interact with its headless page in the editor."}]]},"headers":[],"relativePath":"features/editor-run-control.md","filePath":"features/editor-run-control.md","lastUpdated":1795856808000}'),u={name:"features/editor-run-control.md"};function g(w,t,m,f,b,k){const o=r("Needs");return a(),n("div",null,[t[0]||(t[0]=e("h1",{id:"pause-and-step-from-the-editor",tabindex:"-1"},[i("Pause and step from the editor "),e("a",{class:"header-anchor",href:"#pause-and-step-from-the-editor","aria-label":'Permalink to "Pause and step from the editor"'},"​")],-1)),h(o,{reporter:"",fixtures:"",editor:""}),t[1]||(t[1]=d('<p>A test run the <a href="./editors.html">editor extensions</a> start, or <a href="./terminal-runs.html">one started outside Piwi</a>, can be paused, stepped and resumed from the editor with Piwi&#39;s own commands: no debug session starts, and the IDE&#39;s debugger works as usual beside it. The editor marks the line the test stopped at, and the breakpoints you set or remove reach the run while it goes on. The <a href="./editor-breakpoints.html#pause-a-run">pause bar</a> and Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a> answer the same stops; the code a stop writes is on <a href="./editor-stop-code.html">Code from a pause</a>.</p><h2 id="the-controls" tabindex="-1">The controls <a class="header-anchor" href="#the-controls" aria-label="Permalink to &quot;The controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>VS Code</th><th>JetBrains IDEs</th></tr></thead><tbody><tr><td><strong>Pause</strong></td><td>Stops a running test before its next call that acts on, reads or checks the page</td><td>none</td><td>Pause Program&#39;s</td></tr><tr><td><strong>Resume</strong></td><td>Runs the stopped test on to the next breakpoint</td><td><code>F5</code></td><td>Resume Program&#39;s, <code>F9</code></td></tr><tr><td><strong>Step</strong></td><td>Runs the call and stops before the next one, breakpoint or not</td><td><code>F10</code></td><td>Step Over&#39;s, <code>F8</code></td></tr><tr><td><strong>Run to the cursor</strong></td><td>Stops at the first call on the cursor&#39;s line (on a statement broken over lines, at its call), or at a breakpoint before it</td><td><code>Ctrl+F10</code></td><td>Run to Cursor&#39;s, <code>Alt+F9</code></td></tr><tr><td><strong>Finish</strong></td><td>Runs the test on without stopping at a breakpoint again in this attempt</td><td><code>Shift+F11</code></td><td>Step Out&#39;s, <code>Shift+F8</code></td></tr><tr><td><strong>End the test</strong></td><td><a href="./end-the-test.html">Skips the rest of the test</a>, and a stopped locator call from Playwright 1.62</td><td>none</td><td>none</td></tr><tr><td><strong>Stop</strong></td><td>Ends the run&#39;s process</td><td><code>Shift+F5</code></td><td><strong>Stop the run</strong>, or the Run tool window&#39;s Stop</td></tr></tbody></table><p>The keys are the IDE&#39;s debugger keys (in a JetBrains IDE, <a href="./jetbrains.html">your keymap&#39;s</a>), Piwi&#39;s only while their control applies and the debugger does not take them. On macOS, <code>Cmd+F10</code> runs to the cursor in VS Code. <strong>Pause</strong> and <strong>End the test</strong> have no key in VS Code: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> (search <code>piwi</code>). Within two seconds of an answer, until that worker stops, a key answers no other worker and starts no debug session.</p><p>Each editor puts them where its debugger keeps its own, and in the status item&#39;s menu, whose text says why and where a test stopped: <a href="/reference/editor-commands.html#where-the-run-controls-are">Editor commands</a> lists the places. From its start, before a web server or a global setup lets Playwright report, the item says the run is starting, and <strong>Stop</strong> ends it.</p><p>The item&#39;s line comes from the run, so it counts offline and with the desktop app (<a href="./watch-a-run.html#how-far-it-is">Follow a run</a>); its tooltip names the other tools that have the run open.</p><p><strong>Pause</strong> stops every run Piwi started in this window (a JetBrains IDE&#39;s project), each worker before its next call that Playwright&#39;s debugger stops at (<a href="./editor-breakpoints.html#limits">which calls</a>): a long call or a <code>waitForTimeout</code> finishes first (<a href="./end-the-test.html#while-a-pause-waits-for-a-call">End the test</a> gives up a locator call at once), and a worker between tests stops at the next test&#39;s first call. A test that never stops, under CI or Playwright&#39;s debugger, says why.</p><h2 id="where-the-test-stands" tabindex="-1">Where the test stands <a class="header-anchor" href="#where-the-test-stands" aria-label="Permalink to &quot;Where the test stands&quot;">​</a></h2><p>When a test stops, at a breakpoint, after <strong>Step</strong> or <strong>Pause</strong>, on the line it was run to, at <code>page.pause()</code>, or at <a href="./editor-stop-code.html#a-failure">a failure</a>, the editor opens the file of the call about to run, with the cursor on its line, and marks it: an arrow in the gutter, the debugger&#39;s execution point color, and above it the call, as Playwright names it, with the controls:</p><p><code>Stopped at a breakpoint · Fill &quot;MORNING10&quot; getByLabel(&#39;Coupon code&#39;) · attempt 2</code> Resume Step Finish Write code…</p><p>It says <a href="./watch-a-run.html#where-a-test-stopped">why the test stopped</a>; <code>attempt 2</code> shows on a retry. Its test&#39;s gutter mark shows it paused. Both editors&#39; line holds Resume, Step, Finish and <strong>Write code…</strong> (Resume alone at a failure), VS Code&#39;s lenses giving way; VS Code&#39;s hover holds all controls; the color is <code>piwi.executionPointBackground</code>. In a JetBrains IDE the line is an inlay whose words are links, the arrow&#39;s click and the inlay&#39;s context menu list the controls, and the color is <strong>Settings → Editor → Color Scheme → Piwi → Line a run is stopped at</strong>. The mark goes when the test goes on (from the editor or the bar), ends, or closes its page.</p><figure><img src="'+l+'" alt="VS Code: a test paused at a page object&#39;s line, its hover naming the call that runs next with Resume, Step, Run to the cursor and Finish, and Resume, Step and Finish above the line"><figcaption>A run paused before it types the coupon.</figcaption></figure><p>With several workers stopped, each has its own mark. A stop takes the cursor only on the worker you last answered or worked on, or as the first shown while no step waits; another opens beside your editor, or, in a busy JetBrains IDE, waits in the status bar&#39;s menu. The controls above a line act on its worker, a key or command on the one at the cursor&#39;s line, else the only one shown, else it asks which. A control answers the stop it was shown for: when the test went on meanwhile, it says so and asks nothing.</p><p>The run&#39;s code is your files as they stood when it started. The mark follows lines you add or remove above it, and <strong>Run to the cursor</strong> in an edited file runs to the run&#39;s line for the cursor&#39;s, or says a line written since has none.</p><h2 id="a-headless-run" tabindex="-1">A headless run <a class="header-anchor" href="#a-headless-run" aria-label="Permalink to &quot;A headless run&quot;">​</a></h2><p>A run Piwi starts follows your config, headless by default, unless you turn <a href="./editor-runs.html#how-a-run-starts">headed runs</a> on or an <a href="./editor-breakpoints.html#what-it-needs">older reporter</a> needs it. A headless stop opens its worker&#39;s page (<code>Piwi: worker 1</code> beside VS Code&#39;s editor, the JetBrains tool window&#39;s <strong>Worker 1</strong> tab) with the line&#39;s controls, unless that worker&#39;s <a href="./watch-running-test.html">watch</a> shows it. It keeps its stop until it goes on, after a <strong>Step</strong> or <strong>Run to the cursor</strong> from the editor waits up to 10 seconds for the next, and <strong>Piwi: Show the paused page</strong> (<strong>Tools → Piwi → Run control</strong>) opens it at any stop.</p><figure><img src="'+p+'" alt="VS Code: a headless test paused before it clicks Apply, and beside the editor the Piwi: worker 1 tab showing the cart page with the coupon typed in"><figcaption>A headless run paused before it clicks Apply: the page at the stop, beside the editor.</figcaption></figure><p>Clicking the image picks a locator when the reporter supports it, on Playwright 1.60 or later: it replaces the stopped line&#39;s, and the tab shows the result or refusal.</p><p><strong>Watch</strong> updates the page until you hide or close the tab, resume or switch stops, and <a href="./watch-running-test.html#interact"><strong>Interact</strong></a> plays your input on it, taking the stop. It needs no Piwi Picker (<a href="/guide/remote-development.html">remote development</a>), and older reporters keep the still image. To watch the test before it stops: <a href="./watch-running-test.html">Watch a local test</a>.</p><h2 id="share-with-playwright-tools" tabindex="-1">Share with Playwright tools <a class="header-anchor" href="#share-with-playwright-tools" aria-label="Permalink to &quot;Share with Playwright tools&quot;">​</a></h2><p>At a stop, <strong>Share with Playwright tools</strong> (the stop&#39;s hover and <strong>Piwi: Share the stopped test&#39;s browser with Playwright tools</strong> in VS Code; the stop&#39;s menu and <strong>Tools → Piwi → Run control</strong> in a JetBrains IDE) binds the test&#39;s browser for Playwright&#39;s own tools, so <code>npx playwright cli attach piwi-&lt;run&gt;-w&lt;worker&gt;</code> and Playwright&#39;s dashboard can join it. It is off until you ask, and asks first each time: any process of yours can then read the browser&#39;s pages and run code in them. It stays shared until the test ends; no agent can share it.</p><h2 id="breakpoints-while-the-run-goes-on" tabindex="-1">Breakpoints while the run goes on <a class="header-anchor" href="#breakpoints-while-the-run-goes-on" aria-label="Permalink to &quot;Breakpoints while the run goes on&quot;">​</a></h2><p>A breakpoint you add, remove or toggle applies to the run from its next call, in every worker, later ones included. One that only moves because you edited the lines above it keeps the line the run has, and one you set in an edited file applies to that line of the run&#39;s code. The breakpoints that count are those a run&#39;s start reads: line breakpoints in script files under a Playwright config&#39;s folder, in a Debug with Piwi run (<a href="./editor-breakpoints.html#the-setting">the setting</a> widens this). A logpoint, or a breakpoint that does not suspend, never stops the test; a condition is not read, so a conditional breakpoint stops at each pass.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><figure><img src="'+c+'" alt="A test run&#39;s workers report to the editor service through the run channel, which the IDE and Piwi Picker (over a WebSocket) steer; the pause bar shows in the test&#39;s browser only at a stop"></figure><p>With a reporter newer than 0.59.0, each worker of a Piwi run stays connected to the editor service through a socket only you can read (<code>PIWI_RUN_CHANNEL</code>), saying which test it runs and where it stops. Closing the IDE closes the connections: a stop with no pause bar then goes on, one the bar shows waits there.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>No mark on a breakpoint that never stops.</strong> One on a line with no call Playwright&#39;s debugger stops at looks like any other and does nothing.</li><li><strong>Playwright calls, not JavaScript.</strong> <strong>Step</strong> goes from one Playwright call to the next; stepping through the test&#39;s code stays with the IDE&#39;s debugger.</li><li><strong>No image when the page is unknown.</strong> A stop at a call other than a locator&#39;s (a navigation, a key press) in a browser context with several pages has no image, and refuses Piwi Picker&#39;s <strong>Pick</strong> and <strong>Record</strong>: the worker cannot tell its page. Any page of that context closing ends it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the breakpoints and the pause bar.</li><li><a href="./editor-runs.html">Runs from the editor</a>: the commands that start a run.</li><li><a href="./share-live.html">Share a local run live</a>: for a teammate.</li><li><a href="./debug-in-editor.html">Debug in my editor</a>: a run started from a failure&#39;s page.</li><li><a href="/guide/remote-development.html">Remote development</a>: remote windows and JetBrains Gateway.</li></ul>',30))])}const S=s(u,[["render",g]]);export{P as __pageData,S as default};
